// Parse Bank CSV — n8n Code node (JavaScript, Mode: Run Once for All Items). No require().
// Source of truth: templates/01-bank-reconciliation/code/parse_bank_csv.js; workflow.json embeds this text verbatim
// (ASSUMPTIONS A15). Logic: DESIGN.md §6.2 + §6.5. Input: the items from "Download File" (one per file the Drive
// trigger emitted — several when more than one CSV lands in the folder within one poll, D31), each with binary.data
// holding a bank CSV. Output per input item i (pairedItem.item = i): pre-txn items { _kind: 'txn' } (no
// payer_name_norm / txn_id yet — "Normalize Payer" owns those), { _kind: 'warning', type: 'bad_date' } for rows whose
// date cannot be read, and one { _kind: 'file_stats' } item. Withdrawal / empty / zero deposit rows are ignored (R07).
// Shift_JIS is decoded here with TextDecoder because Extract From File has no shift_jis option (ASSUMPTIONS A6).
// A file whose source mimeType is a Google Sheet (Drive converted the upload) is exported by Download File as UTF-8 CSV
// without BOM, so it is decoded as UTF-8 regardless of CSV_MAPPING.encoding (D22).

// ---- shared helpers: toInt / num / str — identical text in every Code node (DESIGN §6.1) ----
// 数値化：全角→半角、カンマ・¥・円・空白を除去して整数（円）。失敗は toInt() = null / num() = 0
const toInt = (v) => {
  if (v === null || v === undefined) return null;
  if (typeof v === 'number') return Number.isFinite(v) ? Math.trunc(v) : null;
  const s = String(v).normalize('NFKC').replace(/[,\s¥￥円]/g, '');
  if (!/^-?\d+(\.\d+)?$/.test(s)) return null;
  return parseInt(s, 10);
};
const num = (v) => toInt(v) ?? 0;
const str = (v) => (v === null || v === undefined) ? '' : String(v).trim();
// ---- end shared helpers ----

// ---- shared: normalizeDate — identical text in Parse Bank CSV and Parse Mail (DESIGN §6.1 / §6.5) ----
// 受け付ける形式：yyyy/MM/dd, yyyyMMdd, yyyy-MM-dd（仕様）＋ yyyy.MM.dd / yyyy年M月d日 / 区切りありの非ゼロ埋め
// format が 'auto' 以外なら Luxon の fromFormat で厳密に解釈する。返り値は 'yyyy-MM-dd' か null（2026/02/30 等）
function normalizeDate(value, format, tz) {
  const s = str(value).normalize('NFKC');
  if (!s) return null;
  let y, m, d;
  if (format && format !== 'auto') {
    const dt = DateTime.fromFormat(s, format, { zone: tz });           // 明示指定は厳密に
    return dt.isValid ? dt.toFormat('yyyy-MM-dd') : null;
  }
  let mt = s.match(/^(\d{4})(\d{2})(\d{2})$/);                          // yyyyMMdd
  if (!mt) mt = s.match(/^(\d{4})[\/\-.年](\d{1,2})[\/\-.月](\d{1,2})日?/); // yyyy/M/d, yyyy-MM-dd, yyyy.M.d, yyyy年M月d日（末尾に時刻があっても可）
  if (!mt) return null;
  [y, m, d] = [Number(mt[1]), Number(mt[2]), Number(mt[3])];
  const dt = DateTime.fromObject({ year: y, month: m, day: d }, { zone: tz });
  return dt.isValid ? dt.toFormat('yyyy-MM-dd') : null;                 // 2026/02/30 等は null
}
// ---- end shared normalizeDate ----

// ---- バイナリ → 文字列（A6：Extract From File は使わない）----
function decodeCsvBuffer(buf, encoding) {
  // UTF-8 BOM は設定に関わらず UTF-8（fixture B）
  if (buf.length >= 3 && buf[0] === 0xef && buf[1] === 0xbb && buf[2] === 0xbf) {
    return new TextDecoder('utf-8').decode(buf.subarray(3));
  }
  const enc = str(encoding || 'shift_jis').toLowerCase();
  if (enc === 'auto') {
    try { return new TextDecoder('utf-8', { fatal: true }).decode(buf); }   // 不正な UTF-8 なら例外
    catch (e) { return new TextDecoder('shift_jis').decode(buf); }
  }
  return new TextDecoder(enc).decode(buf);   // 'shift_jis' / 'utf-8' / 'euc-jp'。未対応名は RangeError → 実行失敗（意図的）
}

// ---- RFC 4180 風の CSV パース（引用符内のカンマ・改行・"" に対応）----
function parseCsvText(text) {
  const rows = []; let row = []; let field = ''; let inQuotes = false;
  for (let i = 0; i < text.length; i++) {
    const c = text[i];
    if (inQuotes) {
      if (c === '"') { if (text[i + 1] === '"') { field += '"'; i++; } else { inQuotes = false; } }
      else { field += c; }
    } else if (c === '"') { inQuotes = true; }
    else if (c === ',') { row.push(field); field = ''; }
    else if (c === '\r') { /* CRLF の \r は捨てる */ }
    else if (c === '\n') { row.push(field); rows.push(row); row = []; field = ''; }
    else { field += c; }
  }
  if (field !== '' || row.length) { row.push(field); rows.push(row); }
  return rows.filter((r) => r.some((f) => f.trim() !== ''));   // 空行除去
}

// ---- 列対応・出金除外・pre-txn 生成 ----
// rows: string[][]（parseCsvText の出力）。payer_name_norm / txn_id は付けない（Normalize Payer の責務）
function parseBankCsv(rows, m, ctx) {
  const skip = num(m.skip_rows);
  const nk = (s) => str(s).normalize('NFKC');
  const body = rows.slice(skip);
  if (!body.length) throw new Error(`CSV has no header row after skip_rows=${skip}`);
  const header = body[0].map(nk);
  const dataRows = body.slice(1).map((r) => Object.fromEntries(header.map((h, i) => [h, r[i] ?? ''])));
  const col = (name, required) => {
    const key = header.find((h) => h === nk(name));
    if (!key && required) throw new Error(`CSV column not found: "${name}". header = ${header.join(' | ')}`);
    return key || null;
  };
  const dateKey = col(m.date_col, true), payerKey = col(m.payer_col, true), depKey = col(m.deposit_col, true);
  const memoKey = m.memo_col ? col(m.memo_col, false) : null;   // withdraw_col は判定に使わない（deposit が空/0 なら無視）

  const txns = []; const warnings = []; let ignored = 0;
  dataRows.forEach((r, idx) => {
    const rowNo = skip + 2 + idx;                        // 1 始まりの物理行番号（見出し = skip+1。空行は数えない）
    const deposit = toInt(r[depKey]);
    if (!(deposit > 0)) { ignored++; return; }           // R07：出金行・空行・小計行を無視
    const txn_date = normalizeDate(r[dateKey], m.date_format, ctx.tz);
    if (!txn_date) { warnings.push({ type: 'bad_date', row: rowNo, value: str(r[dateKey]) }); return; }
    txns.push({ _kind: 'txn', source: 'bank_csv', txn_date, payer_name_raw: str(r[payerKey]), amount: deposit,
                memo: memoKey ? str(r[memoKey]) : '', _file: ctx.fileName, _row: rowNo });
  });
  return { txns, warnings, ignored_withdraw: ignored };
}

// ---- ノード本体 ----
// DECISION (D31): Google Drive Trigger emits EVERY file created since the last poll as one item each of a single execution
// (GoogleDriveTrigger.node.js poll() → returnJsonArray(files)); Check File Is CSV / Download File run per item. All input items
// are parsed here (not only item 0) and every output item is paired with its source item index.
// DECISION (D22): Download File passes the trigger json through (download.operation.js `json: item.json`), so the source
// mimeType is visible. A Google Sheet export is always UTF-8 (no BOM) → decode as utf-8, not CSV_MAPPING.encoding.
const cfg = $('Config').first().json;
const inputs = $input.all();
const out = [];
for (let i = 0; i < inputs.length; i++) {
  const it = inputs[i];
  const ctx = { tz: cfg.TZ, fileName: it.json.name || it.binary?.data?.fileName || '' };
  const isSheetExport = str(it.json.mimeType) === 'application/vnd.google-apps.spreadsheet';
  const buf = await this.helpers.getBinaryDataBuffer(i, 'data');        // itemIndex, binary property（A12 で動作確認済み）
  const text = decodeCsvBuffer(buf, isSheetExport ? 'utf-8' : cfg.CSV_MAPPING.encoding);
  const { txns, warnings, ignored_withdraw } = parseBankCsv(parseCsvText(text), cfg.CSV_MAPPING, ctx);
  out.push(
    ...txns.map((t) => ({ json: t, pairedItem: { item: i } })),
    ...warnings.map((w) => ({ json: { _kind: 'warning', ...w }, pairedItem: { item: i } })),
    { json: { _kind: 'file_stats', file_name: ctx.fileName, ignored_withdraw, rows_total: txns.length + warnings.length + ignored_withdraw }, pairedItem: { item: i } },
  );
}
return out;

// Parse Mail — n8n Code node (JavaScript, Mode: Run Once for All Items). No require().
// Source of truth: templates/01-bank-reconciliation/code/parse_mail.js; workflow.json embeds this text verbatim
// (ASSUMPTIONS A15). Logic: DESIGN.md §6.3 + §6.5. Input: Gmail Trigger items (Simplify OFF: text / html / subject /
// from / date / id). Each mail yields exactly one item: a pre-txn { _kind: 'txn', source: 'gmail' } (no payer_name_norm /
// txn_id yet — "Normalize Payer" owns those) or a { _kind: 'warning' } item (no_parser_matched / parser_no_capture /
// bad_date). Config MAIL_PARSERS are tried in order; the first whose from_match and subject_match both hold is used (D15).

// ---- shared helpers: toInt / num / str — identical text in every Code node (DESIGN §6.1) ----
// 数値化：全角→半角、カンマ・¥・円・空白を除去して整数（円）。失敗は toInt() = null / num() = 0
const toInt = (v) => {
  if (v === null || v === undefined) return null;
  if (typeof v === 'number') return Number.isFinite(v) ? Math.trunc(v) : null;
  const s = String(v).normalize('NFKC').replace(/[,\s¥￥円]/g, '');
  if (!/^-?\d+(\.\d+)?$/.test(s)) return null;
  return parseInt(s, 10);
};
const num = (v) => toInt(v) ?? 0;
const str = (v) => (v === null || v === undefined) ? '' : String(v).trim();
// ---- end shared helpers ----

// ---- shared: normalizeDate — identical text in Parse Bank CSV and Parse Mail (DESIGN §6.1 / §6.5) ----
// 受け付ける形式：yyyy/MM/dd, yyyyMMdd, yyyy-MM-dd（仕様）＋ yyyy.MM.dd / yyyy年M月d日 / 区切りありの非ゼロ埋め
// format が 'auto' 以外なら Luxon の fromFormat で厳密に解釈する。返り値は 'yyyy-MM-dd' か null（2026/02/30 等）
function normalizeDate(value, format, tz) {
  const s = str(value).normalize('NFKC');
  if (!s) return null;
  let y, m, d;
  if (format && format !== 'auto') {
    const dt = DateTime.fromFormat(s, format, { zone: tz });           // 明示指定は厳密に
    return dt.isValid ? dt.toFormat('yyyy-MM-dd') : null;
  }
  let mt = s.match(/^(\d{4})(\d{2})(\d{2})$/);                          // yyyyMMdd
  if (!mt) mt = s.match(/^(\d{4})[\/\-.年](\d{1,2})[\/\-.月](\d{1,2})日?/); // yyyy/M/d, yyyy-MM-dd, yyyy.M.d, yyyy年M月d日（末尾に時刻があっても可）
  if (!mt) return null;
  [y, m, d] = [Number(mt[1]), Number(mt[2]), Number(mt[3])];
  const dt = DateTime.fromObject({ year: y, month: m, day: d }, { zone: tz });
  return dt.isValid ? dt.toFormat('yyyy-MM-dd') : null;                 // 2026/02/30 等は null
}
// ---- end shared normalizeDate ----

// ---- HTML 本文 → テキスト（text が無いメールだけに使う）----
function htmlToText(html) {
  return str(html)
    .replace(/<br\s*\/?>/gi, '\n').replace(/<\/(p|div|tr|li|h\d)>/gi, '\n').replace(/<[^>]+>/g, '')
    .replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&').replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&quot;/g, '"').replace(/&#39;/g, "'");
}
// from_match / subject_match：大文字小文字無視・NFKC 後の部分一致。needle が空なら常に一致（D15）
const includesCI = (hay, needle) => !needle || str(hay).normalize('NFKC').toLowerCase().includes(str(needle).normalize('NFKC').toLowerCase());
const re = (src) => new RegExp(src, 'u');     // 買い手の正規表現。無効なら SyntaxError → 実行失敗（Config の誤りを隠さない）
// DECISION: Gmail Trigger (Simplify OFF) gives `from` as { text, value: [{ address, name }] } (DESIGN §3.1, to be
// confirmed live in P2 §8.3-4). The pseudocode reads from.text; if a runtime shape has no `text`, fall back to the
// addresses in `value` instead of producing "[object Object]". Strings are used as-is.
const fromText = (f) => {
  if (f && typeof f === 'object') {
    if (str(f.text)) return str(f.text);
    if (Array.isArray(f.value)) return f.value.map((v) => str(v && (v.address || v.name))).filter(Boolean).join(', ');
    return '';
  }
  return str(f);
};

// email: Gmail Trigger（Simplify OFF）の json。戻り値は { txn } または { warning }。txn は pre-txn（txn_id 無し）
function parseMail(email, parsers, ctx) {
  const from = fromText(email.from ?? email.headers?.from);
  const subject = str(email.subject);
  const rawBody = str(email.text) || htmlToText(email.html);            // text 優先
  const body = rawBody.normalize('NFKC');                               // 全角数字・全角コロン → 半角、半角カナ → 全角カナ
  const messageId = str(email.id);
  for (const p of parsers) {
    if (!includesCI(from, p.from_match) || !includesCI(subject, p.subject_match)) continue;
    const amountM = re(p.amount_regex).exec(body);
    const payerM = re(p.payer_regex).exec(body);
    const dateM = p.date_regex ? re(p.date_regex).exec(body) : null;
    const amount = amountM ? toInt(amountM[1]) : null;
    if (!(amount > 0) || !payerM) {
      return { warning: { type: 'parser_no_capture', parser: p.name, message_id: messageId, from, subject } };
    }
    let txn_date = dateM ? normalizeDate(dateM[1], 'auto', ctx.tz) : null;
    if (!txn_date) {
      // 本文に日付が無い／読めない → メールの受信日（TZ の暦日）
      const received = DateTime.fromJSDate(new Date(email.date)).setZone(ctx.tz);
      // DECISION: the pseudocode uses the email date unconditionally; an absent or unparsable `date` would otherwise
      // become the literal "Invalid DateTime" and poison txn_id. Emit a bad_date warning instead (safe default).
      if (!received.isValid) {
        return { warning: { type: 'bad_date', parser: p.name, message_id: messageId, from, subject, value: str(email.date) } };
      }
      txn_date = received.toFormat('yyyy-MM-dd');
    }
    const memo = `${subject} (gmail:${messageId})`;                     // D14：別メールの同額入金を潰さない
    return { txn: { _kind: 'txn', source: 'gmail', txn_date, payer_name_raw: str(payerM[1]), amount, memo, _message_id: messageId, _parser: p.name } };
  }
  return { warning: { type: 'no_parser_matched', message_id: messageId, from, subject } };
}

// ---- ノード本体 ----
const cfg = $('Config').first().json;
const ctx = { tz: cfg.TZ };
const out = [];
$input.all().forEach((item, i) => {
  const r = parseMail(item.json, cfg.MAIL_PARSERS, ctx);
  out.push({ json: r.txn ?? { _kind: 'warning', ...r.warning }, pairedItem: { item: i } });
});
return out;

// Collect Transactions — n8n Code node (JavaScript, Run Once for All Items). DESIGN.md §6.4 / D01.
// Merge point of the three trigger paths. Always returns exactly ONE item
//   { source, txns, warnings, ignored_withdraw, file_name }
// so that Match Invoices never references a node that did not run in this execution.
// Input items: Parse Bank CSV output (pre-txns `_kind:'txn'`, `_kind:'warning'`, one `_kind:'file_stats'` per file),
// Parse Mail output (pre-txns / warnings), or the Config item on the Schedule path (no `_kind` → txns = []).
// payer_name_norm / txn_id are NOT assigned here (Normalize Payer owns them, D27).
// Shared helpers (toInt / num / str) are byte-identical in every Code node of this template (DESIGN.md §6.1).

// ---- shared helpers: toInt / num / str — identical text in every Code node (DESIGN §6.1) ----
// 数値化：全角→半角、カンマ・¥・円・空白を除去して整数（円）。失敗は toInt() = null / num() = 0
const toInt = (v) => {
  if (v === null || v === undefined) return null;
  if (typeof v === 'number') return Number.isFinite(v) ? Math.trunc(v) : null;
  const s = String(v).normalize('NFKC').replace(/[,\s¥￥円]/g, '');
  if (!/^-?\d+(\.\d+)?$/.test(s)) return null;
  return parseInt(s, 10);
};
const num = (v) => toInt(v) ?? 0;
const str = (v) => (v === null || v === undefined) ? '' : String(v).trim();
// ---- end shared helpers ----

// ---- ノード本体 / node body (DESIGN.md §6.4) ----
// DECISION: txn / warning objects are passed through unchanged (their `_kind` key included), exactly as the §6.4
// pseudocode does; §3.4 draws warnings without `_kind` but the extra key is harmless downstream (Build Notification
// reads `type`, and `_kind` never reaches a sheet). Normalize Payer strips `_kind` from txns when it builds txn_id.
// DECISION: the pseudocode's local is named `items`; renamed to `inputs` because `items` is n8n's legacy Code-node alias for
// $input.all() (a sandbox global). Redeclaring it is a SyntaxError in tests/unit/run-code-node.mjs (which passes the alias as a
// parameter) and would only shadow the global inside n8n. Logic is unchanged.
const inputs = $input.all().map((i) => i.json);
const cfg = $('Config').first().json;
const source = ({ 'Watch Drive Folder': 'drive', 'Watch Gmail Inbox': 'gmail', 'Run Daily Rematch': 'schedule' })[cfg.SOURCE] || 'unknown';
const txns = inputs.filter((j) => j._kind === 'txn');
const warnings = inputs.filter((j) => j._kind === 'warning');
// DECISION (D31): Parse Bank CSV emits one file_stats item PER FILE (several files can arrive in one Drive poll), so the stats are
// aggregated here: ignored_withdraw = sum, file_name = the file names joined with ", " (Gmail / Schedule paths have none → 0 / "").
const stats = inputs.filter((j) => j._kind === 'file_stats');
const ignored_withdraw = stats.reduce((sum, f) => sum + num(f.ignored_withdraw), 0);
const file_name = stats.map((f) => str(f.file_name)).filter(Boolean).join(', ');
return [{ json: { source, txns, warnings, ignored_withdraw, file_name }, pairedItem: { item: 0 } }];

// Normalize Payer — n8n Code node (JavaScript, Run Once for All Items). DESIGN.md §6.6 / D27.
// The ONLY place that defines remitter-name normalization, memo_norm and txn_id. Runs right after Read Transactions:
//   $input.all()                      = Read Transactions rows (Always Output Data: an empty sheet yields one {} row → skipped)
//   $('Read Invoices').all()          = invoices rows ({} rows skipped); each row gets _names = normalized customer_name + aliases
//   $('Collect Transactions').first() = { source, txns (pre-txn, no txn_id), warnings, ignored_withdraw, file_name }
// Output: exactly ONE item { source, file_name, ignored_withdraw, warnings, txns, invoices, existing } for Match Invoices.
// Shared helpers toInt / num / str (every Code node) and esc / hiraToKata / splitCsvList / uniq are byte-identical to DESIGN.md §6.1.

// ---- shared helpers: toInt / num / str — identical text in every Code node (DESIGN §6.1) ----
// 数値化：全角→半角、カンマ・¥・円・空白を除去して整数（円）。失敗は toInt() = null / num() = 0
const toInt = (v) => {
  if (v === null || v === undefined) return null;
  if (typeof v === 'number') return Number.isFinite(v) ? Math.trunc(v) : null;
  const s = String(v).normalize('NFKC').replace(/[,\s¥￥円]/g, '');
  if (!/^-?\d+(\.\d+)?$/.test(s)) return null;
  return parseInt(s, 10);
};
const num = (v) => toInt(v) ?? 0;
const str = (v) => (v === null || v === undefined) ? '' : String(v).trim();
// ---- end shared helpers ----
const esc = (s) => s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');            // 正規表現エスケープ
const hiraToKata = (s) => s.replace(/[ぁ-ゖ]/g, (ch) => String.fromCharCode(ch.charCodeAt(0) + 0x60));
const splitCsvList = (s) => str(s).split(/[,、，]/).map((x) => x.trim()).filter(Boolean);
const uniq = (arr) => [...new Set(arr)];

// 仕様の 5 手順。tokens = cfg.LEGAL_ENTITY_TOKENS, stripLeadingDigits = cfg.STRIP_LEADING_DIGITS
// トークン除去は 2 段階：(a) どこでも除去するトークン（振込・フリコミ・株式会社 等）を先に消し、
// (b) そのあとで前株 `X)`（先頭のみ）・後株 `(X`（末尾のみ）を当てる。1 回の走査で長さ順に混ぜると
// fixture A-1（`振込` + 半角の前株略記 + 名義）は前株トークンが先頭に来る前に試されて残り、`カサンプルシヨウジ` になる（fixture で確認済み）
function normalizePayer(raw, tokens, stripLeadingDigits) {
  let s = str(raw).normalize('NFKC');                                   // 1. NFKC：全角英数→半角、半角カナ→全角カナ（濁点合成）、全角括弧→半角
  s = hiraToKata(s);                                                    // 2. ひらがな→カタカナ
  s = s.replace(/[\s　]+/g, '');                                    // 4a. 空白は先に除去（トークン照合を安定させる）
  const toks = uniq((tokens || []).map((t) => hiraToKata(str(t).normalize('NFKC')).replace(/[\s　]+/g, '')).filter(Boolean))
    .sort((a, b) => b.length - a.length);                               // 長いトークンから
  const anchored = (t) => t.endsWith(')') || t.startsWith('(');
  for (const t of toks) {                                               // 3a. どこでも除去（株式会社・振込・フリコミ 等）
    if (!anchored(t)) s = s.split(t).join('');
  }
  for (const t of toks) {                                               // 3b. 法人格略記のアンカー付き除去（D19）
    if (t.endsWith(')')) s = s.replace(new RegExp('^(\\d*)' + esc(t)), '$1');        // 前株形 カ) … 先頭のみ（先頭の数字列は許容）
    else if (t.startsWith('(')) s = s.replace(new RegExp(esc(t) + '$'), '');         // 後株形 (カ … 末尾のみ
  }
  s = s.replace(/[^\p{L}\p{N}ー]/gu, '');                                // 4b. 文字・数字・長音「ー」以外（・ 記号 括弧）を除去
  if (stripLeadingDigits) s = s.replace(/^\d+/, '');                    // 5. 先頭の振込人番号・支店コード
  return s;
}

// memo_norm：NFKC → 空白除去 → `|` を `/` に → 小文字化。記号は残す（shared/sheets-schema.md と同じ定義）
const normalizeMemo = (memo) => str(memo).normalize('NFKC').replace(/[\s　]+/g, '').replace(/\|/g, '/').toLowerCase();

function buildTxnId(txnDateIso, amount, payerNorm, memoNorm) {
  return `${txnDateIso}|${amount}|${payerNorm}|${memoNorm}`;            // §5：date|amount|payer_norm|memo_norm
}

// pre-txn（_kind: 'txn'）→ txn。_file / _row / _message_id / _parser はそのまま通す
function buildTxn(t, cfg) {
  const { _kind, ...rest } = t;
  const payer_name_norm = normalizePayer(t.payer_name_raw, cfg.LEGAL_ENTITY_TOKENS, cfg.STRIP_LEADING_DIGITS);
  const memo_norm = normalizeMemo(t.memo);
  return { txn_id: buildTxnId(t.txn_date, t.amount, payer_name_norm, memo_norm), ...rest, payer_name_norm };
}

// 請求側の比較対象：customer_name の正規化値 + payer_name_alias 各要素の正規化値（重複除去・空除去）
function invoiceNames(inv, cfg) {
  return uniq([inv.customer_name, ...splitCsvList(inv.payer_name_alias)]
    .map((n) => normalizePayer(n, cfg.LEGAL_ENTITY_TOKENS, cfg.STRIP_LEADING_DIGITS)).filter(Boolean));
}

// ---- ノード本体（Read Transactions の直後。常に 1 アイテム）----
const cfg = $('Config').first().json;
const collected = $('Collect Transactions').first().json;               // { source, txns(pre-txn), warnings, ignored_withdraw, file_name }
const invoices = $('Read Invoices').all().map((i) => i.json)
  .filter((i) => str(i.invoice_id))                                     // Always Output Data の {} を除外
  .map((i) => ({ ...i, _names: invoiceNames(i, cfg) }));
const existing = $input.all().map((i) => i.json)
  .filter((r) => str(r.txn_id))
  .map((r) => ({ ...r, payer_name_norm: str(r.payer_name_norm) || normalizePayer(r.payer_name_raw, cfg.LEGAL_ENTITY_TOKENS, cfg.STRIP_LEADING_DIGITS) }));
const txns = (collected.txns || []).map((t) => buildTxn(t, cfg));
return [{ json: { source: collected.source, file_name: collected.file_name, ignored_withdraw: num(collected.ignored_withdraw),
                  warnings: collected.warnings || [], txns, invoices, existing }, pairedItem: { item: 0 } }];

// Match Invoices — n8n Code node (JavaScript, Run Once for All Items). DESIGN.md §6.7 / D07–D13 / D18 / D28.
// The matching core. Input: $input.first().json = the ONE item emitted by Normalize Payer
//   { source, file_name, ignored_withdraw, warnings, txns (with txn_id / payer_name_norm), invoices (with _names), existing }.
// Rules (auto-confirm only 1, 2, 3a, 3b, 3c):
//   1 name+amount (auto) / 2 amount only, one candidate (amount_only) / 3a fee in FEE_SET, one name (fee_deducted)
//   3b unique 2–3 invoice subset of one payer summing to the amount (combined) / 3c amount < remaining, one name (partial, auto)
//   3d overpaid → ambiguous, never confirmed / 4 several candidates → ambiguous / 5 nothing → unmatched.
// Output (single output, split later by Route Match Results on _kind):
//   { _kind: 'invoice_update', invoice_id, status, paid_amount, paid_date, matched_txn_ids, match_confidence, fee_deducted }  (one per invoice, aggregated)
//   { _kind: 'txn_row', <every transactions column of shared/sheets-schema.md> }
//   { _kind: 'summary', date, source, file_name, n, a, b, c, rematched, skipped_existing, skipped_duplicate_in_batch, ignored_withdraw,
//     auto[], needs_review[], ambiguous[], unmatched[], warnings[] }
// Idempotency: txn_ids already in `existing` are skipped (R09); a txn_id already recorded in some invoice's `matched_txn_ids`
// (Update Invoices succeeded but Upsert Transactions failed on a previous run) is not applied again — only its ledger row is
// (re)written (D32); duplicates inside one batch are skipped and counted (D13); on the schedule run only existing
// unmatched / ambiguous rows are re-matched and written back only when changed (D10).
// Shared helpers toInt / num / str (every Code node) and splitCsvList / uniq (also in Normalize Payer) are byte-identical to DESIGN.md §6.1.

// ---- shared helpers: toInt / num / str — identical text in every Code node (DESIGN §6.1) ----
// 数値化：全角→半角、カンマ・¥・円・空白を除去して整数（円）。失敗は toInt() = null / num() = 0
const toInt = (v) => {
  if (v === null || v === undefined) return null;
  if (typeof v === 'number') return Number.isFinite(v) ? Math.trunc(v) : null;
  const s = String(v).normalize('NFKC').replace(/[,\s¥￥円]/g, '');
  if (!/^-?\d+(\.\d+)?$/.test(s)) return null;
  return parseInt(s, 10);
};
const num = (v) => toInt(v) ?? 0;
const str = (v) => (v === null || v === undefined) ? '' : String(v).trim();
// ---- end shared helpers ----
const splitCsvList = (s) => str(s).split(/[,、，]/).map((x) => x.trim()).filter(Boolean);
const uniq = (arr) => [...new Set(arr)];

// 最長共通部分文字列の長さ（候補スコア用。名義は 10〜20 文字なので O(n*m) で十分）
function lcsLength(a, b) {
  let best = 0;
  const prev = new Array(b.length + 1).fill(0);
  for (let i = 1; i <= a.length; i++) {
    let diagonal = 0;
    for (let j = 1; j <= b.length; j++) {
      const tmp = prev[j];
      prev[j] = a[i - 1] === b[j - 1] ? diagonal + 1 : 0;
      if (prev[j] > best) best = prev[j];
      diagonal = tmp;
    }
  }
  return best;
}

// ---- 名義照合（完全一致／包含。短い方が NAME_MIN_CONTAINS 文字以上）----
function nameRank(payerNorm, inv, cfg) {
  if (!payerNorm) return 0;
  let rank = 0;
  const minContains = num(cfg.NAME_MIN_CONTAINS) || 3;
  for (const name of inv._names || []) {
    if (name === payerNorm) return 3;
    const shorter = Math.min(name.length, payerNorm.length);
    if (shorter >= minContains && (payerNorm.includes(name) || name.includes(payerNorm))) rank = Math.max(rank, 2);
    else if (lcsLength(name, payerNorm) >= 2) rank = Math.max(rank, 1);   // 候補提示用の弱い類似（突合には使わない）
  }
  return rank;
}
const nameMatch = (payerNorm, inv, cfg) => nameRank(payerNorm, inv, cfg) >= 2;

// ---- 3b：byName の 2〜3 件の部分集合で remaining の合計 == amount のもの（全列挙。件数が多いときは due_date 昇順で先頭 12 件に制限）----
function subsetsSummingTo(list, target, minK, maxK) {
  const cands = [...list].sort((a, b) => str(a.due_date).localeCompare(str(b.due_date)) || a.invoice_id.localeCompare(b.invoice_id)).slice(0, 12);
  const hits = [];
  const walk = (start, chosen, sum) => {
    if (chosen.length >= minK && sum === target) hits.push([...chosen]);
    if (chosen.length === maxK || sum >= target) return;                     // remaining > 0 なので枝刈り可
    for (let i = start; i < cands.length; i++) walk(i + 1, [...chosen, cands[i]], sum + cands[i].remaining);
  };
  walk(0, [], 0);
  return hits;
}

// ---- 候補スコア（suggested_invoice_ids 上位 3 件）----
// score = nameRank * 10 + amountProximity * 9  … 名義の段階（3 完全 / 2 包含 / 1 部分共通 / 0）が常に金額近似より優先
// amountProximity = 1 - min(1, |remaining - amount| / max(remaining, amount))   … 1.0 = 同額
// withThreshold=true（未消込）のときは nameRank >= 1 または amountProximity >= 0.9（差 10% 以内）の請求だけを候補にする
function rankCandidates(txn, invs, cfg, withThreshold) {
  return invs.map((inv) => {
    const nr = nameRank(txn.payer_name_norm, inv, cfg);
    const diff = Math.abs(inv.remaining - txn.amount);
    const prox = 1 - Math.min(1, diff / Math.max(inv.remaining, txn.amount, 1));
    return { inv, nr, prox, diff, score: nr * 10 + prox * 9 };
  })
  .filter((x) => !withThreshold || x.nr >= 1 || x.prox >= 0.9)
  .sort((x, y) => y.score - x.score || x.diff - y.diff || str(x.inv.due_date).localeCompare(str(y.inv.due_date)) || x.inv.invoice_id.localeCompare(y.inv.invoice_id))
  .slice(0, 3)
  .map((x) => ({ invoice_id: x.inv.invoice_id, remaining: x.inv.remaining, score: Math.round(x.score * 100) / 100 }));
}

// ---- 本体 ----
function matchInvoices(newTxns, invoices, existingRows, cfg, ctx) {
  const today = ctx.now.toFormat('yyyy-MM-dd');
  const nowStr = ctx.now.toFormat("yyyy-MM-dd'T'HH:mm:ssZZ");          // ISO 8601 + JST オフセット（sheets-schema.md の datetime）例 2026-09-23T09:05:12+09:00
  const feeSet = (Array.isArray(cfg.FEE_SET) ? cfg.FEE_SET : []).map(num);   // DECISION: Config の FEE_SET は数値化してから比較（"220" と書かれても効く）

  const summary = { date: today, source: ctx.source, file_name: ctx.file_name, n: 0, a: 0, b: 0, c: 0, rematched: 0,
                    skipped_existing: 0, skipped_duplicate_in_batch: 0, ignored_withdraw: num(ctx.ignored_withdraw),
                    auto: [], needs_review: [], ambiguous: [], unmatched: [], warnings: [...(ctx.warnings || [])] };

  // 台帳の整形：open = currency が JPY（空欄は JPY 扱い）かつ status ∈ {unpaid, partial} かつ remaining > 0。_names は Normalize Payer 済み
  const open = invoices
    .map((i) => ({ ...i, invoice_id: str(i.invoice_id), status: str(i.status).toLowerCase(),
                   amount: num(i.amount), paid_amount: num(i.paid_amount), fee_deducted: num(i.fee_deducted) }))
    .filter((i) => i.status === 'unpaid' || i.status === 'partial')
    .filter((i) => {                                                     // sheets-schema.md：01 は JPY のみ。他通貨は対象外にして警告（D28）
      const c = str(i.currency).toUpperCase();
      if (c && c !== 'JPY') { summary.warnings.push({ type: 'non_jpy_invoice', invoice_id: i.invoice_id, currency: c }); return false; }
      return true;
    })
    .map((i) => ({ ...i, remaining: i.amount - i.paid_amount }))
    .filter((i) => i.remaining > 0);

  const existingById = new Map(existingRows.map((r) => [str(r.txn_id), r]));
  // D32：請求側の matched_txn_ids に既に記録された txn_id → 入金は適用済み（前回 Update Invoices 成功・Upsert Transactions 失敗）。
  // 再適用すると同じ入金が同一名義の別請求に消し込まれるため、台帳行だけを書き直して skip する
  const appliedTo = new Map();                  // txn_id → [invoice_id, …]
  for (const inv of invoices) for (const id of splitCsvList(inv.matched_txn_ids)) appliedTo.set(id, [...(appliedTo.get(id) || []), str(inv.invoice_id)]);
  const consumed = new Set();                    // この実行で消費した invoice_id（全額・一部を問わず）
  const invoiceUpdates = new Map();              // invoice_id → 更新行（集約）
  const txnRows = [];

  // 処理キュー：新規（冪等チェック済み）＋ Schedule 経路なら既存の unmatched / ambiguous
  const queue = []; const seen = new Set();
  for (const t of newTxns) {
    if (existingById.has(t.txn_id)) { summary.skipped_existing++; continue; }          // R09：既存は skip
    if (seen.has(t.txn_id)) { summary.skipped_duplicate_in_batch++; continue; }        // D13：同一実行内の重複
    if (appliedTo.has(t.txn_id)) {                                                       // D32：請求に適用済み → 台帳行の修復のみ
      txnRows.push({ ...txnRowBase(t, nowStr), matched_invoice_ids: appliedTo.get(t.txn_id).join(','), status: 'matched', suggested_invoice_ids: '' });
      summary.skipped_existing++; seen.add(t.txn_id); continue;
    }
    seen.add(t.txn_id); queue.push({ txn: t, isNew: true, prev: null });
  }
  if (ctx.source === 'schedule') {                                                       // D10：再突合は Schedule のみ
    for (const r of existingRows) {
      const st = str(r.status).toLowerCase();
      if (st !== 'unmatched' && st !== 'ambiguous') continue;                          // matched / ignored は対象外
      queue.push({ txn: rowToTxn(r), isNew: false, prev: r });
    }
  }

  for (const { txn, isNew, prev } of queue) {
    const avail = open.filter((i) => !consumed.has(i.invoice_id));
    const byAmt = avail.filter((i) => i.remaining === txn.amount);
    const byName = avail.filter((i) => nameMatch(txn.payer_name_norm, i, cfg));
    const both = byAmt.filter((i) => byName.includes(i));
    let r;
    if (both.length === 1) {                                                       // 1. 名義・金額一致
      r = full([both[0]], 'auto', 0);
    } else if (both.length >= 2) {                                                 // 4. 同額・同名義が複数
      r = ambiguous(both, 'multiple_full_matches');
    } else if (byAmt.length === 1 && byName.length === 0) {                         // 2. 金額のみ一致・候補1
      r = full([byAmt[0]], 'amount_only', 0);
    } else if (byAmt.length >= 2 && byName.length === 0) {                          // 4. 同額請求が複数・名義不一致（R06）
      r = ambiguous(byAmt, 'same_amount_multiple');
    } else if (byAmt.length === 0) {                                               // 3. 金額一致なし
      if (byName.length === 1) {
        const inv = byName[0]; const fee = inv.remaining - txn.amount;
        if (feeSet.includes(fee)) r = full([inv], 'fee_deducted', fee);              // 3a. 手数料差引（名義1件）
        else if (txn.amount < inv.remaining) r = partial(inv);                      // 3c. 一部入金
        else r = ambiguous([inv], 'overpaid');                                      // 3d. 超過 → 自動確定しない（D07）
      } else if (byName.length >= 2) {
        const combos = subsetsSummingTo(byName, txn.amount, 2, 3);
        if (combos.length === 1) r = full(combos[0], 'combined', 0);                // 3b. 合算（一意のときだけ）
        else r = ambiguous(byName, combos.length > 1 ? 'multiple_combinations' : 'name_multiple');   // 4.
      } else {
        r = unmatched();                                                            // 5. 候補なし
      }
    } else {                                                                       // 4. 金額一致と名義一致が別の請求を指す
      r = ambiguous(uniq([...byAmt, ...byName]), 'amount_name_conflict');
    }
    apply(r, txn, isNew, prev);
  }

  return { invoiceUpdates: [...invoiceUpdates.values()], txnRows, summary };

  // ---- 判定結果の生成 ----
  function full(invs, confidence, fee) { return { kind: 'matched', invoices: invs, confidence, fee }; }
  function partial(inv) { return { kind: 'partial', invoices: [inv], confidence: 'auto', fee: 0 }; }
  function ambiguous(cands, reason) { return { kind: 'ambiguous', candidates: cands, reason }; }
  function unmatched() { return { kind: 'unmatched' }; }

  // ---- 適用：invoice 更新行・txn 行・サマリ ----
  // DECISION (T07 / R18 note): a・b・c は新規 txn だけを数え、n = a + b + c を保つ（D11「新規のみ」）。再突合で matched になった既存行は
  //   rematched にだけ数え、明細（auto / needs_review）には載せる。変化のない既存の unmatched / ambiguous は書き戻さず明細にも載せない。
  //   候補だけが変わった既存行は書き戻し、明細にも載せる（人が見る材料）。
  function apply(r, txn, isNew, prev) {
    const line = { txn_date: txn.txn_date, payer_raw: txn.payer_name_raw, amount: txn.amount, source: txn.source };
    const importedAt = prev ? str(prev.imported_at) : nowStr;
    if (isNew) summary.n++;

    if (r.kind === 'matched' || r.kind === 'partial') {
      const ids = [];
      for (const inv of r.invoices) {
        const add = r.confidence === 'combined' ? inv.remaining : txn.amount;      // 合算は各請求の残額を充当
        const paid = inv.paid_amount + add;
        const status = r.kind === 'partial' ? 'partial' : 'paid';                  // fee_deducted は残額-手数料=入金なので paid
        const prevUpd = invoiceUpdates.get(inv.invoice_id);                        // 同一実行で 2 回目は来ない（consumed）が念のため集約
        invoiceUpdates.set(inv.invoice_id, {
          invoice_id: inv.invoice_id, status, paid_amount: paid, paid_date: txn.txn_date,
          matched_txn_ids: uniq([...splitCsvList(prevUpd ? prevUpd.matched_txn_ids : inv.matched_txn_ids), txn.txn_id]).join(','),
          match_confidence: r.confidence, fee_deducted: r.confidence === 'fee_deducted' ? r.fee : inv.fee_deducted });
        consumed.add(inv.invoice_id);                                              // D09：以後の txn からは見えない
        ids.push(inv.invoice_id);
      }
      txnRows.push({ ...txnRowBase(txn, importedAt), matched_invoice_ids: ids.join(','), status: 'matched', suggested_invoice_ids: '' });
      const detail = { ...line, invoice_ids: ids, reason: r.kind === 'partial' ? 'partial' : r.confidence, fee: r.fee,
                       remaining_after: r.kind === 'partial' ? r.invoices[0].remaining - txn.amount : 0 };
      if (r.confidence === 'auto') { if (isNew) summary.a++; summary.auto.push(detail); }       // 規則 1・3c
      else { if (isNew) summary.b++; summary.needs_review.push(detail); }                       // 規則 2・3a・3b → 要確認
      if (!isNew) summary.rematched++;
      return;
    }

    // ambiguous / unmatched：invoice は書かない
    const cands = r.kind === 'ambiguous' ? rankCandidates(txn, r.candidates, cfg, false) : rankCandidates(txn, avail(), cfg, true);
    const suggested = cands.map((c) => c.invoice_id).join(',');
    const status = r.kind;
    const detail = { ...line, reason: r.reason || 'no_candidate', candidates: cands.map((c) => ({ invoice_id: c.invoice_id, remaining: c.remaining })) };
    const changed = isNew || str(prev.status).toLowerCase() !== status || str(prev.suggested_invoice_ids) !== suggested;
    if (changed) {
      txnRows.push({ ...txnRowBase(txn, importedAt), matched_invoice_ids: '', status, suggested_invoice_ids: suggested });   // 既存行は変化があるときだけ書く
    }
    if (isNew) summary.c++;
    if (changed) (status === 'ambiguous' ? summary.ambiguous : summary.unmatched).push(detail);
    function avail() { return open.filter((i) => !consumed.has(i.invoice_id)); }
  }

  function txnRowBase(txn, importedAt) {
    return { txn_id: txn.txn_id, source: txn.source, txn_date: txn.txn_date, payer_name_raw: txn.payer_name_raw,
             payer_name_norm: txn.payer_name_norm, amount: txn.amount, memo: txn.memo, imported_at: importedAt };
  }
  function rowToTxn(r) {           // transactions の既存行 → txn（再突合用。payer_name_norm は Normalize Payer が補完済み）
    return { txn_id: str(r.txn_id), source: str(r.source), txn_date: str(r.txn_date), payer_name_raw: str(r.payer_name_raw),
             payer_name_norm: str(r.payer_name_norm), amount: num(r.amount), memo: str(r.memo) };
  }
}

// ---- 入力 ----
const cfg = $('Config').first().json;
const now = $now.setZone(cfg.TZ);                                        // DECISION: DateTime.now().setZone(TZ) と同値（A12）。$now は単体実行でも固定できる
const data = $input.first().json;                                        // Normalize Payer の 1 アイテム

const result = matchInvoices(data.txns || [], data.invoices || [], data.existing || [], cfg, {
  now, source: data.source, warnings: data.warnings, ignored_withdraw: data.ignored_withdraw, file_name: data.file_name });
return [
  ...result.invoiceUpdates.map((u) => ({ json: { _kind: 'invoice_update', ...u }, pairedItem: { item: 0 } })),
  ...result.txnRows.map((r) => ({ json: { _kind: 'txn_row', ...r }, pairedItem: { item: 0 } })),
  { json: { _kind: 'summary', ...result.summary }, pairedItem: { item: 0 } },
];

// Build Notification — n8n Code node (JavaScript, Run Once for All Items). DESIGN.md §6.8 / §3.7 / D12 / D16 / D28.
// Source of truth: templates/01-bank-reconciliation/code/build_notification.js; workflow.json embeds this text verbatim (ASSUMPTIONS A15).
// Input : $input.first().json = the ONE `_kind: 'summary'` item of Match Invoices (Route Match Results output 2):
//         { date, source, file_name, n, a, b, c, rematched, skipped_existing, skipped_duplicate_in_batch, ignored_withdraw,
//           auto[], needs_review[], ambiguous[], unmatched[], warnings[] }
// Output: exactly ONE item { title, body_text, slack_blocks, line_text, chatwork_text } consumed by Check … Enabled → Notify …,
//         or [] when no notification is due (D12) — then no downstream node runs.
// Copy  : cfg.MESSAGES[LANG].recon_summary (shared/messages.*.json incl. the D16 keys). Sections in order: needs review → ambiguous →
//         unmatched → auto → warnings; each capped at cfg.NOTIFY_MAX_LINES lines (default 40) followed by more_items.
// Limits: Slack header ≤ 150 chars, section text ≤ 3,000 chars (chunked at 2,900; docs.slack.dev Block Kit reference, 2026-09-23);
//         LINE text ≤ 4,900 (API limit 5,000); Chatwork gets the full body (API limit 65,535; ASSUMPTIONS.md 外部 API).
// Shared helpers toInt / num / str (every Code node) and fill / fmtYen (also in Build Error Message) are byte-identical to DESIGN.md §6.1.

// ---- shared helpers: toInt / num / str — identical text in every Code node (DESIGN §6.1) ----
// 数値化：全角→半角、カンマ・¥・円・空白を除去して整数（円）。失敗は toInt() = null / num() = 0
const toInt = (v) => {
  if (v === null || v === undefined) return null;
  if (typeof v === 'number') return Number.isFinite(v) ? Math.trunc(v) : null;
  const s = String(v).normalize('NFKC').replace(/[,\s¥￥円]/g, '');
  if (!/^-?\d+(\.\d+)?$/.test(s)) return null;
  return parseInt(s, 10);
};
const num = (v) => toInt(v) ?? 0;
const str = (v) => (v === null || v === undefined) ? '' : String(v).trim();
// ---- end shared helpers ----

// ---- shared: fill / fmtYen — identical text in Build Notification and Build Error Message (DESIGN §6.1) ----
const fill = (tpl, vars) => String(tpl).replace(/\{(\w+)\}/g, (m, k) => (k in vars ? String(vars[k]) : m));   // {name} 置換。未知のキーは残す
const fmtYen = (n, lang) => Number(n).toLocaleString(lang === 'en' ? 'en-US' : 'ja-JP');                       // 33000 → "33,000"
// ---- end shared fill / fmtYen ----

// ---- ノード本体 / node body (DESIGN.md §6.8) ----
const cfg = $('Config').first().json;
const s = $input.first().json;                                        // summary
const lang = cfg.LANG === 'en' ? 'en' : 'ja';
const m = cfg.MESSAGES && cfg.MESSAGES[lang] && cfg.MESSAGES[lang].recon_summary;   // shared/messages.*.json の recon_summary（D16 のキーを含む）
if (!m) throw new Error(`Config.MESSAGES.${lang}.recon_summary is missing`);         // Config の誤りは隠さず失敗させる（§2.5）
// DECISION: the summary's arrays and counters are read through arr() / num() so a partial or hand-edited summary (missing key,
// numeric string) cannot throw on .filter / .map or print "undefined"; Match Invoices always emits every key, so the normal path is unchanged.
const arr = (v) => (Array.isArray(v) ? v : []);
const warnings = arr(s.warnings);

// D12：Drive / Gmail 実行は常に通知（0 件でも no_transactions）。Schedule 実行は状態が変わったか、取込警告があるときだけ。
// non_jpy_invoice は常設の状態なので Schedule 実行の判定には数えない（USD 請求が 1 件あるだけで毎朝通知しない、D28）
const actionableWarnings = warnings.filter((w) => w.type !== 'non_jpy_invoice');
if (s.source === 'schedule' && num(s.rematched) === 0 && actionableWarnings.length === 0) return [];

const yen = (n) => fmtYen(n, lang);
const reasonText = (d) => {                                            // D16：messages.*.json の recon_summary.reasons
  const r = m.reasons;
  switch (d.reason) {
    case 'amount_only': return r.amount_only;
    case 'fee_deducted': return fill(r.fee_deducted, { fee: yen(d.fee) });
    case 'combined': return r.combined;
    case 'partial': return fill(r.partial, { remaining: yen(d.remaining_after) });
    case 'overpaid': return r.overpaid;
    default: return '';                                                // auto / same_amount_multiple / no_candidate 等は理由句なし
  }
};
const lineMatched = (d) => fill(m.line_item, { txn_date: d.txn_date, payer_raw: d.payer_raw, amount: yen(d.amount),
                                                invoice_id: arr(d.invoice_ids).join(', ') + (reasonText(d) ? ` ${reasonText(d)}` : '') });
const lineCands = (d) => fill(m.line_item_candidates, { txn_date: d.txn_date, payer_raw: d.payer_raw, amount: yen(d.amount),
                                                          candidates: arr(d.candidates).length
                                                            ? arr(d.candidates).map((c) => `${c.invoice_id}(¥${yen(c.remaining)})`).join(', ') + (reasonText(d) ? ` ${reasonText(d)}` : '')
                                                            : '—' });
const lineWarning = (w) => '・' + [w.type, w.parser, w.subject || w.value, w.invoice_id, w.currency].filter(Boolean).join(' ');   // 例: ・non_jpy_invoice INV-2026-022 USD

function section(heading, lines) {                                     // 見出し + 明細（NOTIFY_MAX_LINES 行まで）+ 「…他 N 件」
  if (!lines.length) return null;
  const max = num(cfg.NOTIFY_MAX_LINES) || 40;
  const shown = lines.slice(0, max);
  if (lines.length > max) shown.push(fill(m.more_items, { n: lines.length - max }));
  return [heading, ...shown].join('\n');
}

let title;
let sections = [];
if (num(s.n) === 0 && num(s.rematched) === 0) {
  title = fill(m.no_transactions, { date: str(s.date) });
  if (num(s.skipped_existing)) sections.push(fill(m.skipped_note, { n: num(s.skipped_existing) }));      // 「（処理済みのため skip：N 件）」（R09）
} else {
  title = fill(m.title, { date: str(s.date), n: num(s.n), a: num(s.a), b: num(s.b), c: num(s.c) });
  sections.push(section(m.needs_review_heading, arr(s.needs_review).map(lineMatched)));
  sections.push(section(m.ambiguous_heading, arr(s.ambiguous).map(lineCands)));
  sections.push(section(m.unmatched_heading, arr(s.unmatched).map(lineCands)));
  sections.push(section(m.auto_heading, arr(s.auto).map(lineMatched)));
}
if (warnings.length) sections.push(section(m.warnings_heading, warnings.map(lineWarning)));
sections = sections.filter(Boolean);

const body_text = [title, ...sections].join('\n\n').trim();
const chunk = (text, size) => { const out = []; for (let i = 0; i < text.length; i += size) out.push(text.slice(i, i + size)); return out; };
const slack_blocks = [
  { type: 'header', text: { type: 'plain_text', text: title.slice(0, 150) } },                                   // header text ≤ 150 文字
  ...sections.flatMap((sec) => chunk(sec, 2900).map((t) => ({ type: 'section', text: { type: 'mrkdwn', text: t } }))),   // section text ≤ 3,000 文字
];
return [{ json: { title, body_text, slack_blocks, line_text: body_text.slice(0, 4900), chatwork_text: body_text }, pairedItem: { item: 0 } }];

// Check Notification Results — n8n Code node (JavaScript, Run Once for All Items). DESIGN.md §6.10 / D17 / §8.2.
// Source of truth: templates/01-bank-reconciliation/code/check_notification_results.js; workflow.json embeds this text verbatim (ASSUMPTIONS A15).
// Input : every item that reached Merge Notification Results (Append, 8 inputs): the success output (main[0]) and the error output
//         (main[1]) of Notify Slack / Notify Email / Notify LINE / Notify Chatwork. Build Notification emits ONE item, so each attempted
//         channel contributes exactly one item to exactly one of its two outputs; channels absent from NOTIFY_CHANNELS contribute nothing.
// Error-output item shape (n8n 2.40.5): the engine merges the paired input json into the node's error item
//         (n8n-core workflow-execute.js handleNodeErrorOutput) → { json: { …title, body_text, …, error: <error> } } where <error> is
//         an OBJECT { message, name, stack } (+ json.details) for HTTP Request v4.5 — measured in local n8n, execution 15, see
//         tests/unit/DISCREPANCIES.md — or the message STRING for nodes that push { json: { error: error.message } } (Slack / Gmail sources).
//         Both shapes are handled below; only the message text is reported.
// Output: ONE item { channels_attempted, channels_ok, channels_failed, errors[] }. Throws — and thereby reaches the Error Workflow —
//         only when every attempted channel failed (CLAUDE.md §4.3「全チャネル失敗時は Error Workflow へ」). A partial failure is
//         recorded in this output and in the execution log while the run succeeds (the sheets are already written; a re-run is safe).
// Shared helpers toInt / num / str are byte-identical in every Code node (DESIGN.md §6.1).

// ---- shared helpers: toInt / num / str — identical text in every Code node (DESIGN §6.1) ----
// 数値化：全角→半角、カンマ・¥・円・空白を除去して整数（円）。失敗は toInt() = null / num() = 0
const toInt = (v) => {
  if (v === null || v === undefined) return null;
  if (typeof v === 'number') return Number.isFinite(v) ? Math.trunc(v) : null;
  const s = String(v).normalize('NFKC').replace(/[,\s¥￥円]/g, '');
  if (!/^-?\d+(\.\d+)?$/.test(s)) return null;
  return parseInt(s, 10);
};
const num = (v) => toInt(v) ?? 0;
const str = (v) => (v === null || v === undefined) ? '' : String(v).trim();
// ---- end shared helpers ----

// ---- ノード本体 / node body (DESIGN.md §6.10) ----
// DECISION: the pseudocode's local is named `items`; renamed to `inputs` because `items` is n8n's legacy Code-node alias for $input.all()
// (a sandbox global). Redeclaring it is a SyntaxError in tests/unit/run-code-node.mjs (which passes the alias as a parameter) and would
// only shadow the global inside n8n. Logic is unchanged.
const inputs = $input.all().map((i) => i.json);
const failed = inputs.filter((j) => j.error !== undefined && j.error !== null);      // error 出力のアイテムだけが json.error を持つ
const ok = inputs.length - failed.length;
const messages = failed.map((j) => (typeof j.error === 'string' ? j.error : (j.error.message || JSON.stringify(j.error))));
if (inputs.length > 0 && ok === 0) {
  throw new Error(`All notification channels failed (${failed.length}): ${messages.join(' / ')}`);   // 仕様 §4.3：全チャネル失敗時は Error Workflow へ
}
// DECISION: pairedItem is attached only when an input item exists to pair with. The 0-item case is theoretical — with no data on any
// Merge input n8n never executes this node (NOTIFY_CHANNELS = [] ends at the four IF nodes, §6.10) — but a dangling { item: 0 } is avoided.
return [{ json: { channels_attempted: inputs.length, channels_ok: ok, channels_failed: failed.length, errors: messages },
          ...(inputs.length ? { pairedItem: { item: 0 } } : {}) }];
